function scalePreview(){
  const area=document.querySelector('.canvas-area');
  if(!area)return;
  const width=currentDevice==='mobile'?390:1440,height=currentDevice==='mobile'?844:900;
  const gutter=currentDevice==='mobile'?28:20;
  const availableWidth=Math.max(240,area.clientWidth-gutter);
  const availableHeight=Math.max(320,area.clientHeight-24);
  const scale=Math.min(1,availableWidth/width,availableHeight/height);
  document.documentElement.style.setProperty('--preview-width',`${width}px`);
  document.documentElement.style.setProperty('--preview-height',`${height}px`);
  document.documentElement.style.setProperty('--preview-scale',String(Math.max(.2,scale)));
  document.documentElement.style.setProperty('--preview-stage-width',`${width*Math.max(.2,scale)}px`);
  document.documentElement.style.setProperty('--preview-stage-height',`${height*Math.max(.2,scale)}px`);
}
